          }
        ]
      },
      {
        "evidence": "Pensábamos abrir los martes, pero casi todos trabajaban a esa hora, así que al final atendemos los jueves por la tarde.",
        "skill": 1,
        "format": "multipleChoice",
        "difficulty": "medium",
        "context": null,
        "question": "¿Cuándo se pueden recoger objetos de la biblioteca?",
        "options": [
          {
            "text": "Los martes por la tarde.",
            "isCorrect": false,
            "reason": "Você ouve que terça-feira era o plano inicial, mas ele foi alterado.",
            "misconception": "Escolher o primeiro dia mencionado, antes da correção."
          },
          {
            "text": "Los jueves por la tarde.",
            "isCorrect": true,
            "reason": "Você ouve que, no fim, a biblioteca atende às quintas-feiras à tarde.",
