          },
          {
            "text": "Los sábados durante los talleres.",
            "isCorrect": false,
            "reason": "Você ouve que há oficinas aos sábados, mas não é possível retirar objetos nesse dia.",
            "misconception": "Confundir o dia das oficinas com o horário de empréstimo."
          }
        ]
